INSERT INTO products (id, category_id, name, subtitle, description, price, original_price, stock, sales_count, rating, specs_json, tags_json, is_hot, is_new, created_at, updated_at) VALUES
  ('prod_001', 'cat_digital', 'Apple MacBook Air 13 英寸 M2 8GB / 256GB', 'M2 芯片，无风扇轻薄设计', '采用 M2 芯片和 13.6 英寸 Liquid Retina 显示屏，支持 MagSafe 3 充电。无风扇机身适合随身办公、学习与日常创作；续航随使用方式而变化。', 6999, NULL, 42, 718, 4.7, '{"品牌":"Apple","型号 / 系列":"MacBook Air (M2, 2022)","屏幕":"13.6 英寸，2560 × 1664","内存 / 存储":"8GB / 256GB SSD","重量":"1.24kg"}', '["笔记本","Apple","MacBook Air (M2, 2022)"]', 1, 1, '2026-10-07', '2026-10-07'),
  ('prod_002', 'cat_digital', '索尼 WH-1000XM5 无线降噪耳机', '主动降噪，让聆听更专注', '头戴式无线耳机配有主动降噪、环境声模式和多点连接。开启降噪时官方标称最长播放约 30 小时，适合通勤与旅途，实际续航取决于设置和使用环境。', 2299, NULL, 75, 1432, 4.8, '{"品牌":"Sony","型号 / 系列":"WH-1000XM5","续航":"开启降噪最长约 30 小时","蓝牙":"5.2","重量":"约 250g"}', '["耳机","Sony","WH-1000XM5"]', 1, 0, '2026-10-07', '2026-10-07'),
  ('prod_003', 'cat_digital', '佳明 vívoactive 5 GPS 智能手表', 'AMOLED 触屏，记录运动与日常活动', '搭载 1.2 英寸 AMOLED 触摸屏，支持 GPS 和多种运动应用。智能手表模式续航最长 11 天，常亮显示模式会缩短续航；健康记录不用于医疗诊断。', 1899, NULL, 108, 982, 4.6, '{"品牌":"Garmin","型号 / 系列":"vívoactive 5","屏幕":"1.2 英寸 AMOLED","续航":"智能手表模式最长 11 天","防水等级":"5 ATM"}', '["智能手表","Garmin","vívoactive 5"]', 0, 1, '2026-10-07', '2026-10-07'),
  ('prod_004', 'cat_fashion', 'Nike Pegasus 41 男子公路跑鞋', 'ReactX 泡棉，搭配双 Air Zoom 气垫', 'Pegasus 41 使用 ReactX 泡棉中底，前掌和后跟搭载 Air Zoom 气垫，搭配工程网布鞋面。定位日常公路跑步，穿着感受与尺码、脚型和跑姿有关。', 899, NULL, 130, 2268, 4.7, '{"品牌":"Nike","型号 / 系列":"Pegasus 41","中底":"ReactX 泡棉","缓震":"前掌与后跟 Air Zoom","用途":"公路跑步"}', '["跑鞋","Nike","Pegasus 41"]', 1, 0, '2026-10-07', '2026-10-07'),
  ('prod_005', 'cat_fashion', '珑骧 Le Pliage Original 大号托特包 黑色', '可折叠包身，长柄肩背', 'Le Pliage Original 大号托特包采用再生聚酰胺帆布及皮革饰边，配拉链与按扣翻盖。可折叠设计便于旅行收纳，长柄适合肩背携带日常物品。', 1250, NULL, 86, 1045, 4.6, '{"品牌":"Longchamp","型号 / 系列":"Le Pliage Original L1899089001","款号":"L1899089001","颜色":"黑色","结构":"拉链、按扣翻盖、长柄"}', '["托特包","Longchamp","Le Pliage Original L1899089001"]', 0, 1, '2026-10-07', '2026-10-07'),
  ('prod_006', 'cat_fashion', 'Levi’s 501 Original 男士直筒牛仔裤', '经典直筒，标志性纽扣门襟', '501 Original 是 Levi’s 的经典直筒牛仔裤系列。本目录选用 005010101 纯棉版本，配纽扣门襟；不同洗水及款号的成分和尺码可能不同。', 599, NULL, 160, 1875, 4.5, '{"品牌":"Levi’s","型号 / 系列":"501 Original 005010101","面料":"100% 棉","版型":"Original 直筒","门襟":"纽扣"}', '["牛仔裤","Levi’s","501 Original 005010101"]', 0, 0, '2026-10-07', '2026-10-07'),
  ('prod_007', 'cat_home', '小米 Robot Vacuum X20+ 扫拖机器人', '全能基站，自动集尘与清洗拖布', 'X20+ 配备 LDS 激光导航、双旋转拖布及自动集尘清洗基站，标称最大吸力 6000Pa。支持 Xiaomi Home 应用控制；地面障碍、地毯厚度和清洁设置会影响使用效果。', 2999, NULL, 34, 648, 4.7, '{"品牌":"Xiaomi","型号 / 系列":"Robot Vacuum X20+","最大吸力":"6000Pa","导航":"LDS 激光导航","基站水箱":"4L"}', '["扫拖机器人","Xiaomi","Robot Vacuum X20+"]', 1, 1, '2026-10-07', '2026-10-07'),
  ('prod_008', 'cat_home', '小米 Smart Air Purifier 4 Lite 空气净化器', '颗粒物监测，智能联动净化', '空气净化器提供颗粒物监测、自动模式和应用远程控制。官方颗粒物 CADR 为 360m³/h，标称有效覆盖面积 25–43㎡；适用效果取决于房间与空气条件。', 799, NULL, 66, 826, 4.6, '{"品牌":"Xiaomi","型号 / 系列":"Smart Air Purifier 4 Lite","颗粒物 CADR":"360m³/h","标称覆盖面积":"25–43㎡","控制":"Xiaomi Home 应用"}', '["空气净化器","Xiaomi","Smart Air Purifier 4 Lite"]', 0, 0, '2026-10-07', '2026-10-07'),
  ('prod_009', 'cat_home', 'Fellow Stagg EKG Pro 温控手冲壶', '细口控流，按温度冲泡', 'Stagg EKG Pro 采用细长壶嘴、温度控制和显示屏，适合手冲咖啡及茶饮冲泡。本目录为 Pro 0.9L 型号，电压与插头规格需对应使用地区。', 1699, NULL, 92, 1193, 4.8, '{"品牌":"Fellow","型号 / 系列":"Stagg EKG Pro","容量":"0.9L","壶嘴":"细口鹅颈","控制":"温度设定与显示"}', '["电热壶","Fellow","Stagg EKG Pro"]', 1, 0, '2026-10-07', '2026-10-07'),
  ('prod_010', 'cat_beauty', '安热沙金灿倍护防晒乳 NA 60mL', '轻盈乳液，面部与身体防晒', '日本版 Perfect UV Skincare Milk NA 标注 SPF50+、PA++++，用于面部与身体。按照包装指引足量涂抹并适时补涂；不同地区版本的名称与配方可能不同。', 239, NULL, 180, 2536, 4.7, '{"品牌":"ANESSA","型号 / 系列":"Perfect UV Sunscreen Skincare Milk NA","规格":"60mL","防护等级":"SPF50+ PA++++","适用部位":"面部与身体"}', '["防晒","ANESSA","Perfect UV Sunscreen Skincare Milk NA"]', 1, 0, '2026-10-07', '2026-10-07'),
  ('prod_011', 'cat_beauty', '戴森 Supersonic Nural 吹风机', '头皮保护模式，智能温控干发', 'Supersonic Nural 提供距离感应、头皮保护模式和智能温控，并支持兼容风嘴识别。风嘴组合与电压因销售地区和套装而异，请以对应包装为准。', 3299, NULL, 58, 765, 4.6, '{"品牌":"Dyson","型号 / 系列":"Supersonic Nural","功能":"头皮保护模式","感应":"距离感应","类型":"家用吹风机"}', '["吹风机","Dyson","Supersonic Nural"]', 0, 1, '2026-10-07', '2026-10-07'),
  ('prod_012', 'cat_beauty', 'SK-II 护肤面膜 6 片装', 'PITERA 配方，贴片式护理', 'Facial Treatment Mask 为 SK-II 的独立包装贴片面膜，采用含 PITERA 的精华液。本目录为官方美国版 6 片装，使用方法与成分以实际包装为准。', 699, NULL, 240, 2897, 4.6, '{"品牌":"SK-II","型号 / 系列":"Facial Treatment Mask","数量":"6 片","类型":"贴片面膜","配方特点":"含 PITERA"}', '["面膜","SK-II","Facial Treatment Mask"]', 0, 0, '2026-10-07', '2026-10-07'),
  ('prod_013', 'cat_food', 'Nespresso Arpeggio 咖啡胶囊 10 粒', '深烘焙风味，浓郁可可香调', 'Arpeggio 为 Nespresso Original 系统咖啡胶囊，官方浓度等级为 9，风味呈烘焙和可可香调。每条 10 粒，需配兼容 Original 胶囊咖啡机，不适用于 Vertuo 系统。', 59, NULL, 300, 1842, 4.6, '{"品牌":"Nespresso","型号 / 系列":"Ispirazione Firenze Arpeggio","数量":"10 粒","浓度等级":"9","兼容系统":"Nespresso Original"}', '["咖啡","Nespresso","Ispirazione Firenze Arpeggio"]', 1, 0, '2026-10-07', '2026-10-07'),
  ('prod_014', 'cat_food', 'Blue Diamond 原味杏仁 170g', '原味整粒杏仁，随手加餐', 'Whole Natural 为 Blue Diamond 的原味整粒杏仁。本目录选用 6oz（170g）包装，可直接食用或加入早餐；含杏仁，过敏原信息请查看包装。', 39, NULL, 215, 3278, 4.8, '{"品牌":"Blue Diamond","型号 / 系列":"Whole Natural Almonds","净含量":"170g（6oz）","类型":"整粒杏仁","口味":"原味"}', '["坚果","Blue Diamond","Whole Natural Almonds"]', 1, 0, '2026-10-07', '2026-10-07'),
  ('prod_015', 'cat_food', '瑞士莲 EXCELLENCE 70% 黑巧克力', '70% 可可，细品黑巧风味', 'Lindt EXCELLENCE 70% Cocoa 是板装黑巧克力，适合分块品尝或搭配咖啡。本目录对应美国版 3.5oz 包装；配料及过敏原以包装为准。', 35, NULL, 190, 1568, 4.7, '{"品牌":"Lindt","型号 / 系列":"EXCELLENCE 70% Cocoa","可可含量":"70%","包装规格":"3.5oz","形态":"板装巧克力"}', '["黑巧克力","Lindt","EXCELLENCE 70% Cocoa"]', 0, 1, '2026-10-07', '2026-10-07'),
  ('prod_016', 'cat_digital', 'Apple iPad A16 11 英寸 Wi-Fi 128GB', 'A16 芯片，阅读、笔记与娱乐', 'iPad A16 采用 Liquid Retina 显示屏、USB-C 接口和横向前置摄像头。此款为 Wi-Fi 128GB 版本，支持 Apple Pencil（USB-C）及第一代 Apple Pencil，配件另购。', 2799, NULL, 64, 936, 4.7, '{"品牌":"Apple","型号 / 系列":"iPad (A16)","芯片":"A16","存储":"128GB","屏幕":"Liquid Retina，2360 × 1640"}', '["平板","Apple","iPad (A16)"]', 1, 1, '2026-10-07', '2026-10-07'),
  ('prod_017', 'cat_digital', 'JBL Flip 6 便携蓝牙音箱', '双路扬声器，随身带上音乐', 'Flip 6 采用双路扬声器系统，支持 PartyBoost 连接兼容音箱。具备 IP67 防尘防水等级，官方标称最长播放 12 小时，实际续航随音量和内容变化。', 799, NULL, 118, 1240, 4.6, '{"品牌":"JBL","型号 / 系列":"Flip 6","续航":"最长 12 小时","防护等级":"IP67","蓝牙":"5.1"}', '["音箱","JBL","Flip 6"]', 0, 1, '2026-10-07', '2026-10-07'),
  ('prod_018', 'cat_digital', 'Keychron K8 Pro 机械键盘 RGB 热插拔版', 'QMK/VIA 配置，紧凑 TKL 布局', 'K8 Pro 是支持 QMK/VIA 的 TKL 机械键盘，可通过蓝牙或 USB-C 连接。本目录为 RGB 热插拔配置；轴体、背光与热插拔能力须核对具体购买版本。', 699, NULL, 73, 861, 4.6, '{"品牌":"Keychron","型号 / 系列":"K8 Pro","布局":"TKL 无数字区","连接":"蓝牙 / USB-C 有线","配置":"RGB 热插拔版"}', '["键盘","Keychron","K8 Pro"]', 0, 0, '2026-10-07', '2026-10-07'),
  ('prod_019', 'cat_digital', 'Anker 735 Nano II 65W 氮化镓充电器', '三个接口，桌面与旅行充电', 'Anker 735 A2667 配备两个 USB-C 和一个 USB-A 接口，单 USB-C 最大输出 65W。多口同时使用时会分配总功率，实际充电速度取决于设备和线材。', 299, NULL, 156, 1735, 4.8, '{"品牌":"Anker","型号 / 系列":"735 Charger (Nano II 65W) A2667","总功率":"最高 65W","接口":"2 × USB-C + 1 × USB-A","技术":"GaN II"}', '["充电器","Anker","735 Charger (Nano II 65W) A2667"]', 1, 0, '2026-10-07', '2026-10-07'),
  ('prod_020', 'cat_digital', '罗技 MX Master 3S 无线鼠标', '安静点击，MagSpeed 电磁滚轮', 'MX Master 3S 提供 8000 DPI 传感器、安静点击和 MagSpeed 滚轮，可切换多台兼容设备。支持蓝牙或 Logi Bolt 接收器连接，部分功能依赖 Logi Options+ 软件。', 699, NULL, 95, 1107, 4.7, '{"品牌":"Logitech","型号 / 系列":"MX Master 3S","传感器":"最高 8000 DPI","连接":"蓝牙 / Logi Bolt","滚轮":"MagSpeed"}', '["鼠标","Logitech","MX Master 3S"]', 0, 0, '2026-10-07', '2026-10-07'),
  ('prod_021', 'cat_digital', '罗技 BRIO 4K 网络摄像头', '4K 视频，自动对焦与 HDR', 'BRIO 支持最高 4K 30fps 视频、自动对焦和可调视场角，配有双麦克风。视频分辨率受 USB 连接、应用和系统支持限制，适用于远程会议及内容录制。', 999, NULL, 47, 682, 4.5, '{"品牌":"Logitech","型号 / 系列":"BRIO 4K","视频":"最高 4K 30fps","视场角":"65° / 78° / 90°","对焦":"自动对焦"}', '["摄像头","Logitech","BRIO 4K"]', 0, 1, '2026-10-07', '2026-10-07'),
  ('prod_022', 'cat_digital', '三星 T7 Shield 移动固态硬盘 1TB', '防护机身，随行存储', 'T7 Shield 1TB 配备 USB 3.2 Gen 2 接口及 IP65 防护机身，官方最高顺序读取速度为 1050MB/s。实际速度取决于主机、连接线与传输文件。', 799, NULL, 81, 945, 4.7, '{"品牌":"Samsung","型号 / 系列":"T7 Shield 1TB","容量":"1TB","接口":"USB 3.2 Gen 2","最高读取":"1050MB/s","防护":"IP65"}', '["移动硬盘","Samsung","T7 Shield 1TB"]', 0, 0, '2026-10-07', '2026-10-07'),
  ('prod_023', 'cat_digital', 'Google Nest Hub 第二代智能屏', '家庭控制与影音，一屏查看', 'Nest Hub 第二代配有 7 英寸触摸屏和扬声器，用于兼容智能家居控制、音乐与日程查看。无摄像头；Google 服务、语言和部分功能具有地区限制。', 699, NULL, 38, 514, 4.5, '{"品牌":"Google","型号 / 系列":"Nest Hub (2nd gen)","屏幕":"7 英寸","控制":"触控 / 语音","摄像头":"无"}', '["智能屏","Google","Nest Hub (2nd gen)"]', 0, 1, '2026-10-07', '2026-10-07'),
  ('prod_024', 'cat_digital', '极米 MoGo 2 Pro 便携投影仪', '1080p 投影，自动画面校正', 'MoGo 2 Pro 提供 1080p 分辨率、400 ISO 流明标称亮度和 ISA 2.0 自动校正。内置双 8W 扬声器，需要外接供电；观看效果取决于环境光与投射尺寸。', 2499, NULL, 29, 732, 4.6, '{"品牌":"XGIMI","型号 / 系列":"MoGo 2 Pro","分辨率":"1920 × 1080","标称亮度":"400 ISO 流明","扬声器":"2 × 8W"}', '["投影仪","XGIMI","MoGo 2 Pro"]', 1, 0, '2026-10-07', '2026-10-07'),
  ('prod_025', 'cat_fashion', '优衣库 AIRism 防紫外线连帽外套', 'AIRism 面料，日常轻松叠穿', '这款 AIRism 连帽外套采用全拉链设计，提供防紫外线功能。对应 455412 款号，主体为棉与聚酯纤维混纺；日常穿着可按尺码表选择合适大小。', 249, NULL, 142, 1386, 4.6, '{"品牌":"UNIQLO","型号 / 系列":"AIRism UV Protection Full-Zip Hoodie 455412","主体面料":"62% 棉，38% 聚酯纤维","结构":"全拉链连帽","款号":"455412"}', '["连帽外套","UNIQLO","AIRism UV Protection Full-Zip Hoodie 455412"]', 1, 1, '2026-10-07', '2026-10-07'),
  ('prod_026', 'cat_fashion', 'Patagonia Better Sweater 男士抓绒夹克', '针织外观，抓绒内里', 'Better Sweater 夹克采用 100% 再生聚酯针织抓绒，配全拉链与立领。常规版型适合日常叠穿，带拉链手袋和胸袋。', 1299, NULL, 77, 863, 4.5, '{"品牌":"Patagonia","型号 / 系列":"Better Sweater 25528","面料":"100% 再生聚酯纤维","版型":"常规","款号":"25528"}', '["抓绒夹克","Patagonia","Better Sweater 25528"]', 0, 0, '2026-10-07', '2026-10-07'),
  ('prod_027', 'cat_fashion', '优衣库圆形迷你单肩包', '轻巧弧形包身，日常随身收纳', 'Round Mini Shoulder Bag 采用弧形包身与可调节肩带，可单肩或斜挎携带随身物品。对应 473474 款号；容量、颜色与面料以所选版本为准。', 99, NULL, 126, 1471, 4.7, '{"品牌":"UNIQLO","型号 / 系列":"Round Mini Shoulder Bag 473474","款号":"473474","背带":"可调节","背法":"单肩 / 斜挎"}', '["单肩包","UNIQLO","Round Mini Shoulder Bag 473474"]', 0, 1, '2026-10-07', '2026-10-07'),
  ('prod_028', 'cat_fashion', 'G.H.BASS Larson Weejuns 男士便士乐福鞋', '经典便士鞋型，皮革质感', 'Larson Weejuns 为 G.H.BASS 的经典便士乐福鞋，采用皮革鞋面与便士带细节，适合休闲及轻正式穿搭。鞋底与尺码需核对所选版本，以品牌尺码表选择尺寸。', 1299, NULL, 61, 754, 4.5, '{"品牌":"G.H.BASS","型号 / 系列":"Larson Weejuns Penny Loafer","鞋面":"皮革","鞋型":"便士乐福鞋","穿着":"套穿"}', '["乐福鞋","G.H.BASS","Larson Weejuns Penny Loafer"]', 0, 0, '2026-10-07', '2026-10-07'),
