INSERT INTO product_translations (product_id, locale, name, subtitle, description, specs_json, tags_json) VALUES
  ('prod_001', 'en', 'Apple MacBook Air 13-inch M2 8GB / 256GB', 'M2 performance in a fanless design', 'An M2 laptop with a 13.6-inch Liquid Retina display and MagSafe 3 charging. Its fanless design suits portable work, study and everyday creative tasks; battery life varies with use.', '{"Brand":"Apple","Model / series":"MacBook Air (M2, 2022)","Display":"13.6-inch, 2560 × 1664","Memory / storage":"8GB / 256GB SSD","Weight":"1.24 kg"}', '["Laptop","Apple","MacBook Air (M2, 2022)"]'),
  ('prod_002', 'en', 'Sony WH-1000XM5 Wireless Noise-Cancelling Headphones', 'Active noise cancellation for focused listening', 'Over-ear wireless headphones with active noise cancellation, ambient sound and multipoint connectivity. Rated for up to 30 hours of playback with noise cancellation; actual battery life depends on settings and conditions.', '{"Brand":"Sony","Model / series":"WH-1000XM5","Battery life":"Up to 30 hours with ANC","Bluetooth":"5.2","Weight":"Approx. 250 g"}', '["Headphones","Sony","WH-1000XM5"]'),
  ('prod_003', 'en', 'Garmin vívoactive 5 GPS Smartwatch', 'AMOLED display for fitness and daily activity', 'A GPS smartwatch with a 1.2-inch AMOLED touchscreen and multiple sports apps. Battery life reaches up to 11 days in smartwatch mode and is shorter with always-on display. Wellness tracking is not medical diagnosis.', '{"Brand":"Garmin","Model / series":"vívoactive 5","Display":"1.2-inch AMOLED","Battery life":"Up to 11 days in smartwatch mode","Water rating":"5 ATM"}', '["Smartwatch","Garmin","vívoactive 5"]'),
  ('prod_004', 'en', 'Nike Pegasus 41 Men’s Road Running Shoes', 'ReactX foam with dual Air Zoom units', 'The Pegasus 41 combines a ReactX foam midsole, forefoot and heel Air Zoom units, and an engineered mesh upper for daily road running. Fit and feel depend on size, foot shape and running style.', '{"Brand":"Nike","Model / series":"Pegasus 41","Midsole":"ReactX foam","Cushioning":"Forefoot and heel Air Zoom","Use":"Road running"}', '["Running shoes","Nike","Pegasus 41"]'),
  ('prod_005', 'en', 'Longchamp Le Pliage Original L Tote Black', 'Foldable design with shoulder-length handles', 'The Le Pliage Original large tote uses recycled polyamide canvas with leather trim, a zip and snap flap. Its foldable design packs away for travel, while long handles allow shoulder carrying.', '{"Brand":"Longchamp","Model / series":"Le Pliage Original L1899089001","Reference":"L1899089001","Colour":"Black","Construction":"Zip, snap flap, long handles"}', '["Tote","Longchamp","Le Pliage Original L1899089001"]'),
  ('prod_006', 'en', 'Levi’s 501 Original Men’s Jeans', 'Classic straight leg and button fly', 'The 501 Original is Levi’s classic straight-leg jean. This catalog uses the cotton 005010101 version with a button fly; fabric and sizing can differ across washes and product codes.', '{"Brand":"Levi’s","Model / series":"501 Original 005010101","Fabric":"100% cotton","Fit":"Original straight leg","Fly":"Button"}', '["Jeans","Levi’s","501 Original 005010101"]'),
  ('prod_007', 'en', 'Xiaomi Robot Vacuum X20+', 'All-in-one station for dust collection and mop washing', 'The X20+ combines LDS navigation, rotating mop pads and an auto-emptying, mop-washing station, with rated suction up to 6000 Pa. Xiaomi Home control is supported; obstacles, carpets and settings affect results.', '{"Brand":"Xiaomi","Model / series":"Robot Vacuum X20+","Maximum suction":"6000 Pa","Navigation":"LDS laser navigation","Station water tank":"4 L"}', '["Robot vacuum","Xiaomi","Robot Vacuum X20+"]'),
  ('prod_008', 'en', 'Xiaomi Smart Air Purifier 4 Lite', 'Particle monitoring and connected purification', 'An air purifier with particle monitoring, automatic mode and app control. Rated particle CADR is 360 m³/h with stated effective coverage of 25–43 m²; performance depends on room and air conditions.', '{"Brand":"Xiaomi","Model / series":"Smart Air Purifier 4 Lite","Particle CADR":"360 m³/h","Rated coverage":"25–43 m²","Control":"Xiaomi Home app"}', '["Air purifier","Xiaomi","Smart Air Purifier 4 Lite"]'),
  ('prod_009', 'en', 'Fellow Stagg EKG Pro Electric Kettle', 'Precision pouring with temperature control', 'The Stagg EKG Pro offers a gooseneck spout, temperature control and a display for pour-over coffee and tea. This is the Pro 0.9 L model; voltage and plug specifications must match the region of use.', '{"Brand":"Fellow","Model / series":"Stagg EKG Pro","Capacity":"0.9 L","Spout":"Gooseneck","Control":"Temperature setting and display"}', '["Kettle","Fellow","Stagg EKG Pro"]'),
  ('prod_010', 'en', 'ANESSA Perfect UV Sunscreen Skincare Milk NA 60mL', 'Light milk for face and body sun protection', 'The Japanese Perfect UV Skincare Milk NA carries SPF50+ and PA++++ ratings for face and body. Apply and reapply as directed on the pack; names and formulas may differ by market.', '{"Brand":"ANESSA","Model / series":"Perfect UV Sunscreen Skincare Milk NA","Size":"60 mL","Protection rating":"SPF50+ PA++++","Application":"Face and body"}', '["Sunscreen","ANESSA","Perfect UV Sunscreen Skincare Milk NA"]'),
  ('prod_011', 'en', 'Dyson Supersonic Nural Hair Dryer', 'Scalp Protect mode with intelligent heat control', 'The Supersonic Nural offers proximity sensing, Scalp Protect mode and intelligent heat control, plus recognition of compatible attachments. Attachment sets and voltage vary by market and package.', '{"Brand":"Dyson","Model / series":"Supersonic Nural","Features":"Scalp Protect mode","Sensing":"Proximity sensing","Type":"Home hair dryer"}', '["Hair dryer","Dyson","Supersonic Nural"]'),
  ('prod_012', 'en', 'SK-II Facial Treatment Mask 6-Pack', 'PITERA formula in a sheet mask', 'SK-II Facial Treatment Mask is an individually wrapped sheet mask with a PITERA-containing essence. This catalog uses the official US six-mask pack; follow the ingredients and directions on the supplied package.', '{"Brand":"SK-II","Model / series":"Facial Treatment Mask","Quantity":"6 masks","Type":"Sheet mask","Formula feature":"Contains PITERA"}', '["Sheet mask","SK-II","Facial Treatment Mask"]'),
  ('prod_013', 'en', 'Nespresso Arpeggio Coffee Capsules 10-Pack', 'Dark-roasted character with cocoa notes', 'Arpeggio is an Original-system coffee capsule with a rated intensity of 9 and roasted, cocoa notes. Each sleeve contains 10 capsules and requires a compatible Original machine; it does not fit Vertuo.', '{"Brand":"Nespresso","Model / series":"Ispirazione Firenze Arpeggio","Quantity":"10 capsules","Intensity":"9","System":"Nespresso Original"}', '["Coffee","Nespresso","Ispirazione Firenze Arpeggio"]'),
  ('prod_014', 'en', 'Blue Diamond Whole Natural Almonds 170g', 'Whole natural almonds for everyday snacking', 'Blue Diamond Whole Natural offers whole natural almonds in a 6 oz (170 g) pack. Enjoy them as a snack or with breakfast; contains almonds, so check the package for allergen information.', '{"Brand":"Blue Diamond","Model / series":"Whole Natural Almonds","Net weight":"170 g (6 oz)","Type":"Whole almonds","Flavour":"Whole Natural"}', '["Nuts","Blue Diamond","Whole Natural Almonds"]'),
  ('prod_015', 'en', 'Lindt EXCELLENCE 70% Cocoa Dark Chocolate', '70% cocoa for a dark chocolate moment', 'Lindt EXCELLENCE 70% Cocoa is a dark chocolate bar for tasting in pieces or pairing with coffee. This is the US 3.5 oz pack. Check the package for ingredients and allergens.', '{"Brand":"Lindt","Model / series":"EXCELLENCE 70% Cocoa","Cocoa content":"70%","Pack size":"3.5 oz","Format":"Chocolate bar"}', '["Dark chocolate","Lindt","EXCELLENCE 70% Cocoa"]'),
  ('prod_016', 'en', 'Apple iPad A16 11-inch Wi-Fi 128GB', 'A16 power for reading, notes and entertainment', 'The iPad A16 has a Liquid Retina display, USB-C and a landscape front camera. This is the Wi-Fi 128 GB version. It supports Apple Pencil (USB-C) and Apple Pencil (1st generation); accessories are sold separately.', '{"Brand":"Apple","Model / series":"iPad (A16)","Chip":"A16","Storage":"128 GB","Display":"Liquid Retina, 2360 × 1640"}', '["Tablet","Apple","iPad (A16)"]'),
  ('prod_017', 'en', 'JBL Flip 6 Portable Bluetooth Speaker', 'Two-way sound to take along', 'The Flip 6 has a two-way speaker system and PartyBoost pairing with compatible speakers. It is IP67-rated for dust and water resistance, with up to 12 hours of playback depending on volume and content.', '{"Brand":"JBL","Model / series":"Flip 6","Battery life":"Up to 12 hours","Protection":"IP67","Bluetooth":"5.1"}', '["Speaker","JBL","Flip 6"]'),
  ('prod_018', 'en', 'Keychron K8 Pro RGB Hot-Swappable Keyboard', 'QMK/VIA configuration in a TKL layout', 'The K8 Pro is a QMK/VIA-compatible TKL mechanical keyboard with Bluetooth and USB-C connectivity. This catalog selects the RGB hot-swappable configuration; switches, lighting and hot-swap support depend on the selected version.', '{"Brand":"Keychron","Model / series":"K8 Pro","Layout":"TKL without numpad","Connectivity":"Bluetooth / USB-C wired","Configuration":"RGB hot-swappable"}', '["Keyboard","Keychron","K8 Pro"]'),
  ('prod_019', 'en', 'Anker 735 Nano II 65W Charger', 'Three ports for desktop and travel charging', 'The Anker 735 A2667 has two USB-C ports and one USB-A port, with up to 65 W from a single USB-C port. Power is shared when charging multiple devices; speed depends on devices and cables.', '{"Brand":"Anker","Model / series":"735 Charger (Nano II 65W) A2667","Total output":"Up to 65 W","Ports":"2 × USB-C + 1 × USB-A","Technology":"GaN II"}', '["Charger","Anker","735 Charger (Nano II 65W) A2667"]'),
  ('prod_020', 'en', 'Logitech MX Master 3S Wireless Mouse', 'Quiet clicks with MagSpeed scrolling', 'The MX Master 3S offers an 8000 DPI sensor, quiet clicks and MagSpeed scrolling with multi-device switching. Connect by Bluetooth or Logi Bolt; some features require Logi Options+.', '{"Brand":"Logitech","Model / series":"MX Master 3S","Sensor":"Up to 8000 DPI","Connectivity":"Bluetooth / Logi Bolt","Scroll wheel":"MagSpeed"}', '["Mouse","Logitech","MX Master 3S"]'),
  ('prod_021', 'en', 'Logitech BRIO 4K Webcam', '4K video with autofocus and HDR', 'BRIO supports up to 4K at 30 fps, autofocus, adjustable field of view and dual microphones. Available resolution depends on USB connectivity, software and system support for meetings and recording.', '{"Brand":"Logitech","Model / series":"BRIO 4K","Video":"Up to 4K 30 fps","Field of view":"65° / 78° / 90°","Focus":"Autofocus"}', '["Webcam","Logitech","BRIO 4K"]'),
  ('prod_022', 'en', 'Samsung T7 Shield Portable SSD 1TB', 'Durable storage for life on the move', 'The T7 Shield 1 TB combines USB 3.2 Gen 2 with an IP65-rated enclosure. Rated sequential reads reach up to 1050 MB/s; actual speed depends on the host, cable and files.', '{"Brand":"Samsung","Model / series":"T7 Shield 1TB","Capacity":"1 TB","Interface":"USB 3.2 Gen 2","Maximum read":"1050 MB/s","Protection":"IP65"}', '["Portable SSD","Samsung","T7 Shield 1TB"]'),
  ('prod_023', 'en', 'Google Nest Hub 2nd Gen', 'Home controls and entertainment in one display', 'The second-generation Nest Hub has a 7-inch touchscreen and speaker for compatible smart-home controls, music and schedules. It has no camera; Google services, languages and features vary by region.', '{"Brand":"Google","Model / series":"Nest Hub (2nd gen)","Display":"7-inch","Control":"Touch / voice","Camera":"None"}', '["Smart display","Google","Nest Hub (2nd gen)"]'),
  ('prod_024', 'en', 'XGIMI MoGo 2 Pro Portable Projector', '1080p projection with automatic adjustment', 'The MoGo 2 Pro offers 1080p resolution, rated 400 ISO lumens and ISA 2.0 adjustment, plus dual 8 W speakers. External power is required; viewing quality depends on ambient light and image size.', '{"Brand":"XGIMI","Model / series":"MoGo 2 Pro","Resolution":"1920 × 1080","Rated brightness":"400 ISO lumens","Speakers":"2 × 8 W"}', '["Projector","XGIMI","MoGo 2 Pro"]'),
  ('prod_025', 'en', 'UNIQLO AIRism UV Protection Full-Zip Hoodie', 'AIRism comfort for everyday layering', 'This AIRism full-zip hoodie offers UV protection for everyday layering. Product 455412 uses a cotton and polyester body; consult the size guide for fit.', '{"Brand":"UNIQLO","Model / series":"AIRism UV Protection Full-Zip Hoodie 455412","Body fabric":"62% cotton, 38% polyester","Construction":"Full zip with hood","Product ID":"455412"}', '["Hoodie","UNIQLO","AIRism UV Protection Full-Zip Hoodie 455412"]'),
  ('prod_026', 'en', 'Patagonia Men’s Better Sweater Fleece Jacket', 'Sweater-knit exterior with fleece warmth', 'The Better Sweater jacket uses 100% recycled polyester sweater-knit fleece with a full zip and stand-up collar. Its regular fit, zipped hand pockets and chest pocket suit everyday layering.', '{"Brand":"Patagonia","Model / series":"Better Sweater 25528","Fabric":"100% recycled polyester","Fit":"Regular","Style number":"25528"}', '["Fleece jacket","Patagonia","Better Sweater 25528"]'),
  ('prod_027', 'en', 'UNIQLO Round Mini Shoulder Bag', 'A compact curved bag for daily essentials', 'The Round Mini Shoulder Bag has a curved body and adjustable strap for shoulder or crossbody carry. This is product 473474; capacity, colour and fabric depend on the selected version.', '{"Brand":"UNIQLO","Model / series":"Round Mini Shoulder Bag 473474","Product ID":"473474","Strap":"Adjustable","Carry":"Shoulder / crossbody"}', '["Shoulder bag","UNIQLO","Round Mini Shoulder Bag 473474"]'),
  ('prod_028', 'en', 'G.H.BASS Men’s Larson Weejuns Penny Loafer', 'Classic penny loafer styling in leather', 'The Larson Weejuns is G.H.BASS’s classic penny loafer with a leather upper and penny strap detail for casual and smart-casual styling. Check the selected version for sole construction and sizing.', '{"Brand":"G.H.BASS","Model / series":"Larson Weejuns Penny Loafer","Upper":"Leather","Style":"Penny loafer","Closure":"Slip-on"}', '["Loafers","G.H.BASS","Larson Weejuns Penny Loafer"]'),
  ('prod_029', 'en', 'UNIQLO AIRism Cotton Oversized Half-Sleeve T-Shirt', 'A cotton look with AIRism comfort', 'This Uniqlo U T-shirt combines AIRism cotton-blend fabric, an oversized cut and half sleeves for everyday wear or layering. This listing is one shirt.', '{"Brand":"UNIQLO","Model / series":"AIRism Cotton Oversized T-Shirt 465185","Fit":"Oversized","Sleeves":"Half sleeve","Product ID":"465185"}', '["T-shirt","UNIQLO","AIRism Cotton Oversized T-Shirt 465185"]'),
  ('prod_030', 'en', 'Fjällräven Kånken Classic Backpack 16L', 'Vinylon F fabric in the classic square design', 'The classic Kånken uses Vinylon F fabric, a wide-opening main zip, front and side pockets, and a removable seat pad. This is the classic 16 L bag, not the Laptop series with a separate laptop compartment.', '{"Brand":"Fjällräven","Model / series":"Kånken F23510","Capacity":"16 L","Fabric":"Vinylon F","Article number":"F23510"}', '["Backpack","Fjällräven","Kånken F23510"]'),
  ('prod_031', 'en', 'Nike Challenger Dri-FIT Men’s 5-inch Running Shorts', 'Dri-FIT performance with a brief liner', 'The Challenger running shorts feature Nike Dri-FIT technology and a built-in brief liner. The 5-inch inseam suits running and training, with pockets for small essentials.', '{"Brand":"Nike","Model / series":"Challenger Dri-FIT 5-inch","Inseam":"5-inch","Technology":"Nike Dri-FIT","Liner":"Brief liner"}', '["Shorts","Nike","Challenger Dri-FIT 5-inch"]'),
  ('prod_032', 'en', 'Patagonia Wavefarer Bucket Hat', 'Packable brim for days outdoors', 'The Wavefarer bucket hat has lightweight fabric and an all-around brim for outdoor days and travel, with packable construction. This is style 29157; consult the brand size guide for fit.', '{"Brand":"Patagonia","Model / series":"Wavefarer Bucket Hat 29157","Style number":"29157","Style":"Bucket hat","Packing":"Packable"}', '["Hat","Patagonia","Wavefarer Bucket Hat 29157"]'),
  ('prod_033', 'en', 'Acne Studios Fringe Wool Scarf Narrow Black', 'Wool fabric with fringed ends', 'Acne Studios’ narrow wool scarf has a rectangular shape, fringed ends and a brand label for autumn and winter styling. This listing is the black CA0210 version; follow its care label.', '{"Brand":"Acne Studios","Model / series":"Fringe Wool Scarf Narrow CA0210","Material":"Wool","Style number":"CA0210","Colour":"Black"}', '["Scarf","Acne Studios","Fringe Wool Scarf Narrow CA0210"]'),
  ('prod_034', 'en', 'IKEA RÅSKOG Utility Cart White', 'Three storage tiers to move where needed', 'The RÅSKOG utility cart has three open storage tiers and casters for kitchens, bathrooms or desks. This listing uses white article 30586783; check its official instructions for dimensions and loads.', '{"Brand":"IKEA","Model / series":"RÅSKOG 30586783","Tiers":"3","Colour":"White","Article number":"30586783"}', '["Utility cart","IKEA","RÅSKOG 30586783"]'),
  ('prod_035', 'en', 'IKEA MARKUS Office Chair Dark Gray', 'Mesh backrest with adjustable seat height', 'The MARKUS office chair has a high mesh backrest, height adjustment and a reclining function. This listing is article 90289172; assess its fit against your height and desk setup.', '{"Brand":"IKEA","Model / series":"MARKUS 90289172","Backrest":"High mesh back","Adjustment":"Seat height / recline","Article number":"90289172"}', '["Office chair","IKEA","MARKUS 90289172"]'),
  ('prod_036', 'en', 'IKEA ROSENSKÄRM Ergonomic Pillow', 'Two-height shape for side and back sleeping', 'ROSENSKÄRM uses foam and memory foam in a contoured shape for side and back sleepers, with a removable washable cover. Choose the pillow edge height to suit your sleeping position.', '{"Brand":"IKEA","Model / series":"ROSENSKÄRM 90444371","Fill":"Foam / memory foam","Sleeping position":"Side / back","Cover":"Removable and washable"}', '["Pillow","IKEA","ROSENSKÄRM 90444371"]'),
  ('prod_037', 'en', 'IKEA TERTIAL Work Lamp Dark Gray', 'Adjustable arm directs light where needed', 'The TERTIAL work lamp has an adjustable arm and shade for directing light over a desk. Choose a compatible bulb separately.', '{"Brand":"IKEA","Model / series":"TERTIAL 20355434","Adjustment":"Arm and shade","Colour":"Dark gray","Article number":"20355434"}', '["Desk lamp","IKEA","TERTIAL 20355434"]'),
  ('prod_038', 'en', 'MUJI Ultrasonic Aroma Diffuser 100mL', 'Ultrasonic fragrant mist with soft light', 'This MUJI diffuser disperses water and compatible essential oils with ultrasonic mist, lighting and a timer. The 100 mL model is for local aromatherapy rather than whole-room humidification.', '{"Brand":"MUJI","Model / series":"Ultrasonic Aroma Diffuser 100mL","Tank":"100 mL","Method":"Ultrasonic mist","Functions":"Light / timer"}', '["Aroma diffuser","MUJI","Ultrasonic Aroma Diffuser 100mL"]'),
  ('prod_039', 'en', 'IKEA MULIG Indoor/Outdoor Drying Rack', 'Foldable drying for indoor and outdoor use', 'MULIG is a folding drying rack for indoor and outdoor use, with multiple drying rails that pack away when idle. Check the official article details for materials and load limits.', '{"Brand":"IKEA","Model / series":"MULIG 50228755","Use":"Indoor / outdoor","Storage":"Foldable","Article number":"50228755"}', '["Drying rack","IKEA","MULIG 50228755"]'),
  ('prod_040', 'en', 'Le Creuset Signature Round Dutch Oven 4.5qt', 'Enameled cast iron for braising and baking', 'The Signature round Dutch oven has enameled cast iron surfaces for slow cooking, braising and oven dishes, including induction use. This is the 4.5 qt size; follow temperature limits for the pot and lid components.', '{"Brand":"Le Creuset","Model / series":"Signature Round Dutch Oven 4.5qt","Capacity":"4.5 qt","Material":"Enameled cast iron","Cooktops":"Induction compatible"}', '["Dutch oven","Le Creuset","Signature Round Dutch Oven 4.5qt"]'),
  ('prod_041', 'en', 'Aqara Curtain Driver E1 Track Version', 'Retrofit curtains for scheduled opening', 'The Curtain Driver E1 Track Version automates existing curtains through Zigbee 3.0 and requires a compatible Aqara hub. Check rail shape and dimensions before installation.', '{"Brand":"Aqara","Model / series":"Curtain Driver E1 Track Version","Connectivity":"Zigbee 3.0","Version":"Track version","Requirement":"Compatible Aqara hub"}', '["Curtain driver","Aqara","Curtain Driver E1 Track Version"]'),
  ('prod_042', 'en', 'IKEA DYTÅG Linen Duvet Cover and Pillowcase Dark Gray', 'Prewashed linen with a relaxed texture', 'DYTÅG uses prewashed linen with a relaxed, textured finish. Article 30518812 is a single duvet cover and pillowcase set: one cover and one pillowcase, without a sheet or duvet insert.', '{"Brand":"IKEA","Model / series":"DYTÅG 30518812","Duvet cover size":"150 × 200 cm","Pillowcase size":"50 × 60 cm","Fabric":"Linen"}', '["Bedding","IKEA","DYTÅG 30518812"]'),
  ('prod_043', 'en', 'CeraVe Foaming Facial Cleanser', 'Foaming cleansing with three ceramides', 'Foaming Facial Cleanser is designed for normal to oily skin with three ceramides, hyaluronic acid and niacinamide, without fragrance. It lathers during washing; pack sizes vary by market.', '{"Brand":"CeraVe","Model / series":"Foaming Facial Cleanser","Type":"Foaming cleanser","Skin type":"Normal to oily","Fragrance":"Fragrance-free"}', '["Cleanser","CeraVe","Foaming Facial Cleanser"]'),
  ('prod_044', 'en', 'The Ordinary Hyaluronic Acid 2% + B5 with Ceramides 30mL', 'Hyaluronic acid and B5 for daily hydration', 'This water-based serum combines multiple forms of hyaluronic acid, vitamin B5 and ceramides for hydration and barrier support. The listing is the 30 mL with Ceramides formulation; consult its application and compatibility guidance.', '{"Brand":"The Ordinary","Model / series":"Hyaluronic Acid 2% + B5 (with Ceramides)","Size":"30 mL","Formula":"Hyaluronic acid 2% + B5 + ceramides","Type":"Water-based serum"}', '["Serum","The Ordinary","Hyaluronic Acid 2% + B5 (with Ceramides)"]'),
  ('prod_045', 'en', 'MAC Retro Matte Lipstick Ruby Woo 3g', 'Classic Ruby Woo in a retro matte finish', 'Ruby Woo is the classic red shade in MAC’s Retro Matte lipstick line, with a matte finish. This is the traditional 3 g Retro Matte version, rather than another formula or mini size sharing the shade name.', '{"Brand":"MAC","Model / series":"Retro Matte Ruby Woo","Size":"3 g","Shade":"Ruby Woo","Finish":"Retro Matte"}', '["Lipstick","MAC","Retro Matte Ruby Woo"]'),
  ('prod_046', 'en', 'FOREO LUNA 4 Facial Cleansing Device', 'Silicone touchpoints with T-Sonic cleansing', 'LUNA 4 uses silicone touchpoints and T-Sonic pulsations for facial cleansing, with app settings. Touchpoint layouts vary by skin-type version; adjust intensity and frequency according to personal needs and instructions.', '{"Brand":"FOREO","Model / series":"LUNA 4","Touchpoints":"Silicone","Technology":"T-Sonic","Settings":"FOREO app"}', '["Cleansing device","FOREO","LUNA 4"]'),
  ('prod_047', 'en', 'Breo iSee4 Eye Massager', 'Foldable design with warming massage', 'The iSee4 has a folding design with eye massage and warming functions. The official description specifies warmth around 107.6°F (42°C). It is for everyday relaxation; follow the brand’s usage guidance.', '{"Brand":"Breo","Model / series":"iSee4","Warming temperature":"Approx. 42°C","Construction":"Foldable","Type":"Eye massager"}', '["Eye massager","Breo","iSee4"]'),
  ('prod_048', 'en', 'L’Occitane Almond Shower Oil 250mL', 'Almond-scented cleansing that emulsifies with water', 'Almond Shower Oil is a body cleanser with sweet almond oil that emulsifies on contact with water and carries an almond scent. This is the 250 mL pack; it contains fragrance, so check the ingredients if sensitive.', '{"Brand":"L’Occitane","Model / series":"Almond Shower Oil","Size":"250 mL","Application":"Body cleansing","Formula feature":"Contains sweet almond oil"}', '["Shower oil","L’Occitane","Almond Shower Oil"]'),
  ('prod_049', 'en', 'Batiste Original Dry Shampoo', 'Classic fresh scent for a root refresh', 'Original Dry Shampoo refreshes roots and absorbs excess oil between washes with a classic fresh scent. Massage and brush through as instructed on the pack; it does not replace regular washing.', '{"Brand":"Batiste","Model / series":"Original Dry Shampoo","Type":"Dry shampoo spray","Scent":"Original","Use":"Between washes"}', '["Dry shampoo","Batiste","Original Dry Shampoo"]'),
  ('prod_050', 'en', 'Huda Beauty Nude Obsessions Light Eyeshadow Palette', 'Nude shades in matte and shimmer textures', 'The Nude Obsessions line offers Light, Medium and Rich colour themes; this listing selects Light. It combines matte, shimmer and metallic shades for everyday eye looks.', '{"Brand":"Huda Beauty","Model / series":"Nude Obsessions Light","Theme":"Light","Line":"Nude Obsessions","Finishes":"Matte / shimmer / metallic"}', '["Eyeshadow","Huda Beauty","Nude Obsessions Light"]'),
  ('prod_051', 'en', 'CeraVe Daily Moisturizing Lotion', 'Lightweight oil-free daily moisture', 'Daily Moisturizing Lotion contains three ceramides and hyaluronic acid for normal to dry skin. Its lightweight, oil-free formula is fragrance-free; sizes and ingredients should be checked on the regional pack.', '{"Brand":"CeraVe","Model / series":"Daily Moisturizing Lotion","Skin type":"Normal to dry","Formula":"Oil-free","Fragrance":"Fragrance-free"}', '["Moisturizing lotion","CeraVe","Daily Moisturizing Lotion"]'),
  ('prod_052', 'en', 'Quaker Old Fashioned Oats', 'Whole-grain oats for a versatile breakfast', 'Quaker Old Fashioned Oats are rolled oats for hot oatmeal or breakfast with fruit and nuts. Follow the package directions for preparation.', '{"Brand":"Quaker","Model / series":"Old Fashioned Oats","Type":"Rolled oats","Grain":"Whole-grain oats","Preparation":"Cook as directed on the pack"}', '["Oats","Quaker","Old Fashioned Oats"]'),
  ('prod_053', 'en', 'Ocean Spray Craisins Original Dried Cranberries 170g', 'Sweet-tart cranberries for breakfast and baking', 'Craisins Original are sweetened dried cranberries for snacking, salads, oats and baking. This is the 6 oz pack and contains added sugar.', '{"Brand":"Ocean Spray","Model / series":"Craisins Original","Size":"6 oz (approx. 170 g)","Flavour":"Original","Type":"Sweetened dried cranberries"}', '["Dried fruit","Ocean Spray","Craisins Original"]'),
  ('prod_054', 'en', 'Twinings Earl Grey Extra Strong Tea 20 Bags', 'Bergamot notes with a stronger black tea', 'Earl Grey Extra Strong is a bergamot-flavoured black tea in a 20-bag pack. It contains caffeine and is prepared with hot water as directed.', '{"Brand":"Twinings","Model / series":"Earl Grey Extra Strong","Quantity":"20 tea bags","Tea type":"Black tea","Flavour":"Bergamot"}', '["Tea bags","Twinings","Earl Grey Extra Strong"]'),
  ('prod_055', 'en', 'Bertolli Extra Virgin Olive Oil Rich Taste', 'Full-bodied fruitiness for salads and cooking', 'Bertolli Rich Taste is an extra virgin olive oil blend described by the brand as cold pressed with full-bodied fruity flavour for salads, pasta and cooking. Check the supplied pack for the blend’s origin information.', '{"Brand":"Bertolli","Model / series":"Extra Virgin Olive Oil Rich Taste","Grade":"Extra virgin","Line":"Rich Taste","Use":"Dressings / cooking"}', '["Olive oil","Bertolli","Extra Virgin Olive Oil Rich Taste"]'),
  ('prod_056', 'en', 'Twinings English Breakfast Tea 20 Bags', 'A classic black tea blend for breakfast', 'English Breakfast is Twinings’ black tea blend for drinking plain or with milk. This listing is a caffeinated 20-bag pack.', '{"Brand":"Twinings","Model / series":"English Breakfast","Quantity":"20 tea bags","Tea type":"Black tea blend","Format":"Tea bags"}', '["Black tea","Twinings","English Breakfast"]'),
  ('prod_057', 'en', 'Jack Link’s Original Beef Jerky', 'Smoky savoury flavour for a portable snack', 'Jack Link’s Original Beef Jerky is seasoned beef jerky with slow-cooked, hardwood-smoked flavour. Pack sizes and nutrition vary by market; check the nutrition panel on the supplied pack.', '{"Brand":"Jack Link’s","Model / series":"Original Beef Jerky","Type":"Beef jerky","Flavour":"Original","Character":"Hardwood smoke"}', '["Beef jerky","Jack Link’s","Original Beef Jerky"]'),
  ('prod_058', 'en', 'Royal Dansk Danish Butter Cookies Blue Tin 12oz', 'Five butter cookie styles in the classic blue tin', 'Royal Dansk’s blue tin contains five classic butter cookie styles for sharing or pairing with tea. This is the 12 oz tin.', '{"Brand":"Royal Dansk","Model / series":"Danish Butter Cookies 12oz","Size":"12 oz","Packaging":"Blue tin","Assortment":"5 classic cookie styles"}', '["Cookies","Royal Dansk","Danish Butter Cookies 12oz"]'),
  ('prod_059', 'en', 'Perrier Original Carbonated Mineral Water', 'French mineral water with lively bubbles', 'Perrier Original is French carbonated mineral water described as sugar-free and zero-calorie, for drinking plain or mixing. Glass, can and plastic formats are available; check the supplied pack size.', '{"Brand":"Perrier","Model / series":"Original Carbonated Mineral Water","Type":"Carbonated mineral water","Origin":"France","Flavour":"Original"}', '["Sparkling water","Perrier","Original Carbonated Mineral Water"]'),
  ('prod_060', 'en', 'Bob’s Red Mill 7 Grain Hot Cereal', 'Seven grains for a warm breakfast', '7 Grain Hot Cereal is a whole-grain blend to cook with water as instructed and serve with fruit or nuts. It includes gluten-containing grains; check allergens.', '{"Brand":"Bob’s Red Mill","Model / series":"7 Grain Hot Cereal","Type":"Hot multigrain cereal","Grain count":"7","Cooking":"About 10 minutes, follow pack directions"}', '["Grains","Bob’s Red Mill","7 Grain Hot Cereal"]'),
  ('prod_061', 'en', 'Kobo Clara BW eReader', 'Carta 1300 e-ink for comfortable reading', 'The Clara BW has a 6-inch E Ink Carta 1300 display, 16 GB storage, adjustable warm front light and IPX8 water resistance. Store and content support vary by region; battery life depends on reading habits.', '{"Brand":"Kobo","Model / series":"Clara BW","Display":"6-inch E Ink Carta 1300","Storage":"16 GB","Water resistance":"IPX8"}', '["eReader","Kobo","Clara BW"]'),
  ('prod_062', 'en', 'DJI Osmo Action 4 Action Camera', 'A 1/1.3-inch sensor for action footage', 'The Osmo Action 4 combines a 1/1.3-inch CMOS sensor, 155° field of view and electronic stabilization, supporting up to 4K 120 fps. Rated waterproof depth is 18 m without a case, subject to closed covers and specified conditions.', '{"Brand":"DJI","Model / series":"Osmo Action 4","Video":"Up to 4K 120 fps","Sensor":"1/1.3-inch CMOS","Weight":"145 g"}', '["Action camera","DJI","Osmo Action 4"]'),
  ('prod_063', 'en', 'Anker 633 Magnetic Battery 10000mAh', 'Magnetic charging with a foldable stand', 'The Anker 633 A1641 has rated 10000 mAh cell capacity, magnetic wireless charging and a folding stand, with up to 20 W USB-C charging. Wireless output is up to 7.5 W; this is not a Qi2 15 W model.', '{"Brand":"Anker","Model / series":"633 Magnetic Battery A1641","Cell capacity":"10000 mAh","Wireless output":"Up to 7.5 W","USB-C output":"Up to 20 W"}', '["Power bank","Anker","633 Magnetic Battery A1641"]'),
  ('prod_064', 'en', 'Dell UltraSharp U2724D 27-inch Monitor', 'IPS Black with a 120Hz refresh rate', 'The U2724D has a 27-inch QHD IPS Black panel, up to 120 Hz refresh and an adjustable stand. Its USB-C is for data; do not confuse it with the U2724DE’s USB-C video and power delivery features.', '{"Brand":"Dell","Model / series":"UltraSharp U2724D","Size":"27-inch","Resolution":"2560 × 1440","Refresh rate":"Up to 120 Hz"}', '["Monitor","Dell","UltraSharp U2724D"]'),
  ('prod_065', 'en', 'Shokz OpenFit Open-Ear Earbuds', 'Open-ear comfort with ambient awareness', 'OpenFit uses an open-ear hook design and DirectPitch technology, with up to 7 hours per charge or 28 hours with its case. IP54 protection applies to the earbuds; an open-ear design does not replace attention to surroundings.', '{"Brand":"Shokz","Model / series":"OpenFit","Battery life":"Up to 7 hours per charge","With charging case":"Up to 28 hours total","Protection":"Earbuds IP54"}', '["Open-ear earbuds","Shokz","OpenFit"]'),
  ('prod_066', 'en', 'Wacom Intuos M Bluetooth Pen Tablet', 'Battery-free pen for drawing and annotation', 'The Intuos M Bluetooth uses a battery-free pen with 4096 pressure levels, shortcut keys and Bluetooth or USB connectivity. It is a pen tablet requiring a compatible computer, not a display tablet.', '{"Brand":"Wacom","Model / series":"Intuos M Bluetooth CTL-6100WL","Pressure levels":"4096","Model":"CTL-6100WL","Connectivity":"Bluetooth / USB"}', '["Pen tablet","Wacom","Intuos M Bluetooth CTL-6100WL"]'),
  ('prod_067', 'en', 'Patagonia Men’s Torrentshell 3L Rain Jacket', 'Three-layer waterproof breathability for wet days', 'The Torrentshell 3L uses an H2No-standard three-layer waterproof and breathable construction, with an adjustable hood, pit zips and self-storage in a pocket. Follow the brand’s guidance for wet-weather use and care.', '{"Brand":"Patagonia","Model / series":"Torrentshell 3L 85241","Construction":"3-layer","Standard":"H2No Performance Standard","Style number":"85241"}', '["Rain jacket","Patagonia","Torrentshell 3L 85241"]'),
  ('prod_068', 'en', 'Fjällräven Canvas Belt', 'Adjustable length with a metal buckle', 'Fjällräven’s Canvas Belt can be shortened to fit and has a metal buckle and tip. Its official material is 100% acrylic.', '{"Brand":"Fjällräven","Model / series":"Canvas Belt","Material":"100% acrylic","Width":"3.8 cm","Length":"120 cm, can be shortened"}', '["Belt","Fjällräven","Canvas Belt"]'),
  ('prod_069', 'en', 'Ray-Ban Original Wayfarer Classic RB2140 Sunglasses', 'The classic Wayfarer silhouette', 'The RB2140 Original Wayfarer Classic line offers multiple frame and lens combinations in the classic silhouette. Polarization is not assumed for every version; check the exact lens option and size.', '{"Brand":"Ray-Ban","Model / series":"Original Wayfarer Classic RB2140","Model":"RB2140","Line":"Original Wayfarer Classic","Lens configuration":"Depends on selected version"}', '["Sunglasses","Ray-Ban","Original Wayfarer Classic RB2140"]'),
  ('prod_070', 'en', 'Crocs Classic Clog', 'Lightweight comfort with a pivoting heel strap', 'The Classic Clog uses lightweight Croslite material, ventilation ports and a pivoting heel strap for easy everyday wear. It is not a specialist slip-resistant work shoe; take care on wet surfaces.', '{"Brand":"Crocs","Model / series":"Classic Clog 10001","Material":"Croslite","Heel":"Pivoting heel strap","Style number":"10001"}', '["Clogs","Crocs","Classic Clog 10001"]'),
  ('prod_071', 'en', 'UNIQLO Premium Linen Long-Sleeve Shirt', '100% linen for relaxed daily styling', 'The Premium Linen long-sleeve shirt uses 100% linen, a button front and curved hem for wearing alone or layering. This is product 433475.', '{"Brand":"UNIQLO","Model / series":"Premium Linen Long-Sleeve Shirt 433475","Fabric":"100% linen","Sleeves":"Long sleeve","Product ID":"433475"}', '["Shirt","UNIQLO","Premium Linen Long-Sleeve Shirt 433475"]'),
  ('prod_072', 'en', 'Samsonite Freeform Carry-On Spinner', 'Hardside packing with spinner mobility', 'The Freeform Carry-On Spinner combines a hardside shell, spinner wheels and telescopic handle for short trips. Airline cabin rules vary; check exterior dimensions including wheels and handles.', '{"Brand":"Samsonite","Model / series":"Freeform Carry-On Spinner","Construction":"Hardside","Wheels":"Spinner wheels","Line":"Freeform"}', '["Suitcase","Samsonite","Freeform Carry-On Spinner"]'),
  ('prod_073', 'en', 'Xiaomi Smart Multifunctional Rice Cooker 3L', 'App control for everyday meal planning', 'This 3 L smart multifunctional rice cooker supports Xiaomi Home control and multiple cooking programs. The official description allows 1–5 cups of uncooked rice; this is the smart multifunctional model, not the IH version.', '{"Brand":"Xiaomi","Model / series":"Smart Multifunctional Rice Cooker 3L","Capacity":"3 L","Control":"Xiaomi Home app","Rice quantity":"1–5 cups uncooked rice"}', '["Rice cooker","Xiaomi","Smart Multifunctional Rice Cooker 3L"]'),
  ('prod_074', 'en', 'IKEA SAMLA Clear Storage Box with Lid 22L', 'Clear storage keeps contents visible', 'The clear SAMLA box keeps clothes, household items and seasonal supplies visible. This is one 22 L box with a lid.', '{"Brand":"IKEA","Model / series":"SAMLA S69440822","Capacity":"22 L","Dimensions":"39 × 28 × 28 cm","Quantity":"1 box and 1 lid"}', '["Storage box","IKEA","SAMLA S69440822"]'),
  ('prod_075', 'en', 'IKEA VÅGSJÖN Cotton Bath Towel White', 'Terry and woven stripes for daily bathing', 'The VÅGSJÖN bath towel combines cotton terry and woven stripes for everyday drying. This is white article 80350985, supplied as one towel.', '{"Brand":"IKEA","Model / series":"VÅGSJÖN 80350985","Material":"100% cotton","Size":"28 × 55 inches","Quantity":"1 towel"}', '["Bath towel","IKEA","VÅGSJÖN 80350985"]'),
  ('prod_076', 'en', 'TIMEMORE Chestnut C3 Hand Grinder', 'Manual grinding with adjustable coarseness', 'The Chestnut C3 uses an S2C burr design and adjustable coarseness for small-batch manual coffee grinding. Capacity follows the current brand C3-series page at about 20 g; check the exact version’s specifications.', '{"Brand":"TIMEMORE","Model / series":"Chestnut C3","Method":"Manual grinding","Capacity":"Approx. 20 g","Burr design":"S2C"}', '["Coffee grinder","TIMEMORE","Chestnut C3"]'),
  ('prod_077', 'en', 'Manduka PRO Yoga Mat 6mm Standard', 'Supportive cushioning for yoga and stretching', 'The standard Manduka PRO mat is about 6 mm thick with a closed-cell surface for yoga and stretching. It measures about 180 × 66 cm and weighs around 3.4 kg; grip depends on use and care.', '{"Brand":"Manduka","Model / series":"PRO Yoga Mat 6mm","Dimensions":"Approx. 180 × 66 cm","Thickness":"Approx. 6 mm","Weight":"Approx. 3.4 kg"}', '["Yoga mat","Manduka","PRO Yoga Mat 6mm"]'),
  ('prod_078', 'en', 'IKEA HEKTAR Floor Lamp Dark Gray', 'An adjustable shade for reading beside the sofa', 'The HEKTAR floor lamp has an industrial-style metal shade that directs light for reading or local room lighting. This is single-head article 70216544; a bulb is sold separately.', '{"Brand":"IKEA","Model / series":"HEKTAR 70216544","Construction":"Single lamp head","Colour":"Dark gray","Article number":"70216544"}', '["Floor lamp","IKEA","HEKTAR 70216544"]'),
  ('prod_079', 'en', 'Hada Labo Gokujun Hyaluronic Acid Lotion 170mL', 'Hyaluronic hydration after cleansing', 'The Japanese Gokujun Hyaluronic Acid Lotion is used for moisturizing after cleansing. This listing follows Rohto’s official 170 mL Gokujun Lotion, rather than Premium, an emulsion or a different regional version.', '{"Brand":"Hada Labo","Model / series":"Gokujun Hyaluronic Acid Lotion","Size":"170 mL","Type":"Hydrating lotion / toner","Line":"Gokujun"}', '["Toner","Hada Labo","Gokujun Hyaluronic Acid Lotion"]'),
  ('prod_080', 'en', 'Kiehl’s Ultra Facial Cream 50mL', 'Lightweight texture for daily facial moisture', 'Ultra Facial Cream is Kiehl’s facial moisturizer with squalane and a lightweight texture. This is the 50 mL size; check ingredients on the supplied pack.', '{"Brand":"Kiehl’s","Model / series":"Ultra Facial Cream","Size":"50 mL","Formula feature":"Contains squalane","Application":"Face"}', '["Face cream","Kiehl’s","Ultra Facial Cream"]'),
  ('prod_081', 'en', 'L’Occitane Shea Butter Hand Cream 30mL', 'Shea butter care in a portable tube', 'L’Occitane Shea Butter Hand Cream is for daily hand moisturizing. This listing is one 30 mL tube; it contains fragrance, and ingredients depend on the supplied version.', '{"Brand":"L’Occitane","Model / series":"Shea Butter Hand Cream","Size":"30 mL","Quantity":"1 tube","Application":"Hands"}', '["Hand cream","L’Occitane","Shea Butter Hand Cream"]'),
  ('prod_082', 'en', 'Jo Malone London Wood Sage & Sea Salt Cologne 30mL', 'Sea salt and sage with a woody character', 'Wood Sage & Sea Salt Cologne features brand-listed notes of ambrette seeds, sea salt and sage with a fresh woody character. This is the 30 mL cologne.', '{"Brand":"Jo Malone London","Model / series":"Wood Sage & Sea Salt Cologne","Size":"30 mL","Notes":"Ambrette seeds / sea salt / sage","Type":"Cologne"}', '["Fragrance","Jo Malone London","Wood Sage & Sea Salt Cologne"]'),
  ('prod_083', 'en', 'Real Techniques Everyday Essentials Set', 'Four brushes and a sponge for everyday makeup', 'Everyday Essentials includes blush, face, crease and setting brushes plus a Miracle Complexion Sponge for basic makeup steps. It contains four brushes and one sponge.', '{"Brand":"Real Techniques","Model / series":"Everyday Essentials","Contents":"4 brushes + 1 sponge","Sponge":"Miracle Complexion Sponge","Use":"Face / blush / eyes / setting"}', '["Makeup tools","Real Techniques","Everyday Essentials"]'),
  ('prod_084', 'en', 'Burt’s Bees Beeswax Lip Balm 4.2g', 'Beeswax and peppermint for everyday lip care', 'The classic Beeswax Lip Balm has a beeswax formula with peppermint oil in a portable twist-up tube. This listing follows the official 0.15 oz / 4.2 g size with a peppermint scent.', '{"Brand":"Burt’s Bees","Model / series":"Beeswax Lip Balm","Size":"4.2 g (0.15 oz)","Feature":"Contains beeswax and peppermint oil","Packaging":"Twist-up tube"}', '["Lip balm","Burt’s Bees","Beeswax Lip Balm"]'),
  ('prod_085', 'en', 'Rowse Clear Honey', 'Honey for breakfast and baking', 'Rowse Clear Honey is runny honey in a glass jar for toast, breakfast and baking. Check the supplied pack for floral origin and net weight.', '{"Brand":"Rowse","Model / series":"Clear Honey","Type":"Runny honey","Packaging":"Glass jar","Use":"Breakfast / baking"}', '["Honey","Rowse","Clear Honey"]'),
  ('prod_086', 'en', 'Barilla Spaghetti 500g', 'Durum wheat spaghetti for classic pasta dishes', 'Barilla Spaghetti is made with durum wheat semolina and water for pairing with tomato and other pasta sauces. This is one 500 g pack; the linked version lists about 8 minutes cooking time, adjusted to package directions and preference.', '{"Brand":"Barilla","Model / series":"Spaghetti","Net weight":"500 g","Ingredients":"Durum wheat semolina / water","Cooking time":"Approx. 8 minutes"}', '["Pasta","Barilla","Spaghetti"]'),
  ('prod_087', 'en', '7D Dried Mangoes 100g', 'Philippine mango with a sweet-tart taste', '7D Dried Mangoes use Philippine mango processed with cane sugar for a sweet-tart taste. This is the 100 g pack and contains added sugar.', '{"Brand":"7D","Model / series":"Dried Mangoes","Net weight":"100 g","Type":"Dried mango","Added sugar":"Contains cane sugar"}', '["Dried mango","7D","Dried Mangoes"]'),
  ('prod_088', 'en', 'Oatly Oat Drink Barista Edition 1L', 'Made for coffee, also enjoyed on its own', 'Oatly Barista Edition is an oat drink designed for coffee and foaming, also suitable to drink on its own. This is one 1 L carton; check the regional pack for ingredients and storage after opening.', '{"Brand":"Oatly","Model / series":"Oat Drink Barista Edition","Volume":"1 L","Type":"Oat drink","Edition":"Barista Edition"}', '["Oat drink","Oatly","Oat Drink Barista Edition"]'),
  ('prod_089', 'en', 'Lee Kum Kee Chili Garlic Sauce 226g', 'Garlic and chilli for dipping and cooking', 'Lee Kum Kee Chili Garlic Sauce combines chilli and garlic for dipping, noodles and cooking. This is the official Hong Kong 226 g jar; consult its pack for ingredients, allergens and storage after opening.', '{"Brand":"Lee Kum Kee","Model / series":"Chili Garlic Sauce","Net weight":"226 g","Flavour":"Chilli and garlic","Packaging":"Jar"}', '["Chilli sauce","Lee Kum Kee","Chili Garlic Sauce"]'),
  ('prod_090', 'en', 'Nissin Cup Noodles Seafood 75g', 'Seafood flavour in a convenient cup', 'Nissin Cup Noodles Seafood is a seafood-flavoured instant noodle cup. This listing follows the Singapore official 75 g cup; prepare as directed and check ingredients and allergens.', '{"Brand":"Nissin","Model / series":"Cup Noodles Seafood","Net weight":"75 g","Flavour":"Seafood","Quantity":"1 cup"}', '["Cup noodles","Nissin","Cup Noodles Seafood"]')
